import { Injectable } from '@angular/core';
import { ApiService } from '../api/api.service';
import { EntityService } from './entity.service';
import { Entity } from '../../entities/entity';
import {Observable, Subscription} from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class EntityCacheService<T extends Entity> {
  // entityName -> (filterKey -> entity array)
  private cache: Map<string, Map<string, T[]>> = new Map();

  constructor(
    private apiService: ApiService,
    private entityService: EntityService
  ) {}

  private generateKey(params: { [key: string]: any }): string {
    return JSON.stringify(params, Object.keys(params).sort());
  }

  private getEntityName(entityClass: new () => T): string {
    return entityClass.name;
  }

  loadEntities(
    endpoint: string,
    entityClass: new () => T,
    params: { [key: string]: any } = {},
    forceReload = false,
    onLoaded?: (entities: T[]) => void
  ): Subscription | void {
    const entityName = this.getEntityName(entityClass);
    const key = this.generateKey(params);

    if (!this.cache.has(entityName)) {
      this.cache.set(entityName, new Map());
    }

    const entityCache = this.cache.get(entityName)!;
    if (!forceReload && entityCache.has(key)) {
      return; // already loaded
    }

    return this.apiService.get<T[]>(endpoint, params).subscribe({
      next: data => {
        const mapped = this.entityService.matchDataToEntity<T>(data, entityClass);
        entityCache.set(key, mapped);
        if (onLoaded) {
          onLoaded(mapped);
        }
      },
      error: err => {
        console.error(`Error fetching ${entityName} from ${endpoint}:`, err);
      }
    });
  }

  filterCachedEntities(
    entityClass: new () => T,
    params: { [key: string]: any }
  ): T[] {
    const entityName = this.getEntityName(entityClass);
    const key = this.generateKey(params);

    return this.cache.get(entityName)?.get(key) || [];
  }

  clearCache(entityClass?: new () => T): void {
    if (entityClass) {
      const entityName = this.getEntityName(entityClass);
      this.cache.delete(entityName);
    } else {
      this.cache.clear();
    }
  }
}

import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class EntityService {

  constructor() { }

  matchDataToEntity<T>(data: any[], entityClass: { new (): T }): T[] {
    if (!Array.isArray(data)) return [];
    // @ts-ignore
    return data.map(item => Object.assign(new entityClass() as T, item));
  }

  filterEntities<T>(courses: T[], params: { [key: string]: any }): T[] {
    if (!courses || !Array.isArray(courses) || courses.length === 0) {
      return [];
    }

    return courses.filter(course => {
      let matches = true;
      const courseObject = course as { [key: string]: any };
      for (const key in params) {
        if (params.hasOwnProperty(key)) {
          const value = params[key];
          if (courseObject[key] != value) {
            matches = false;
            break;
          }
        }
      }
      return matches;
    });
  }
}

import {Injectable} from '@angular/core';
import {EntityCacheService} from './entity-cache.service';
import {LessonSection} from '../../entities/lesson-section';
import {ApiService} from '../api/api.service';
import {Observable} from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class LessonSectionService {

  constructor(
    private cacheService: EntityCacheService<LessonSection>,
    private apiService: ApiService
  ) {
  }

  /** Load many into cache (optionally filtered) */
  loadSections(params: {
    [key: string]: any
  } = {}, onLoaded?: ((entities: LessonSection[]) => void) | undefined, forceReload = false): void {
    this.cacheService.loadEntities('lessonSection/index', LessonSection, params, forceReload, onLoaded);
  }

  /** Get many from cache (optionally filtered) */
  getSections(params: { [key: string]: any } = {}): LessonSection[] {
    return this.cacheService.filterCachedEntities(LessonSection, params);
  }

  /** Get one from cache by id (undefined if not present) */
  getSectionById(id: number): LessonSection | undefined {
    // If your cache has a direct getter, prefer that; otherwise filter:
    return this.cacheService
      .filterCachedEntities(LessonSection, {id})
      .find(s => s.id === id);
  }

  /** Fetch one from API (does not write to cache unless your ApiService does it internally) */
  fetchSection(id: number): Observable<LessonSection> {
    return this.apiService.get<LessonSection>(`lessonSection/${id}`);
  }

  /** Create via API */
  createSection(section: LessonSection): Observable<LessonSection> {
    return this.apiService.post<LessonSection>('lessonSection/create', section);
  }

  /** Update via API */
  updateSection(section: LessonSection): Observable<LessonSection> {
    return this.apiService.put<LessonSection>(`lessonSection/${section.id}`, section);
  }

  /** Delete via API */
  deleteSection(id: number): Observable<void> {
    return this.apiService.delete<void>(`lessonSection/${id}`);
  }

  /** Convenience: create or update depending on presence of id */
  saveSection(section: LessonSection): Observable<LessonSection> {
    return section.id ? this.updateSection(section) : this.createSection(section);
  }

  /** Clear cache for this entity type */
  clearCache(): void {
    this.cacheService.clearCache(LessonSection);
  }
}

